import React, { useContext, useEffect, useState } from 'react';
import { ThemeContext } from '../../context/ThemeContext';
import { Button, Card, Col, ListGroup, ListGroupItem } from 'react-bootstrap';
import Contacto from './Contacto';
import perfil from '../../assets/img/imagenes/perfil-cv.png';
import tag from '../../assets/img/imagenes/tag-cv.png';
import cv from '../../assets/files/ohdfi02463f.pdf';
import cvEng from '../../assets/files/jahjsxa5466ds.pdf';

const Bio = () => {
    const { texts, download } = useContext (ThemeContext)
    const [ mostrar, setMostrar ] = useState (false)

    useEffect(()=>{
        if ( download === 'file-esp'){
            setMostrar(true)
        } else {
            setMostrar(false)
        }
    }, [download])
    
    return (
        <>
            <Col md={5} >
                <Card className='card-noborder'>
                    <Card.Img src={perfil}></Card.Img>
                    <div style={{position:'relative', border:'0px'}}>
                        <Card.Img src={tag}></Card.Img>
                        { mostrar ? 
                        
                        <Button style={{position: 'absolute', right: '-8px', top: '260px'}} href={cv} download='cv-sebastiansierra.pdf'>
                            {texts.download}
                        </Button>
                        :
                        <Button style={{position: 'absolute', right: '-8px', top: '260px'}} href={cvEng} download='cv-sebastiansierra.pdf'>
                            {texts.download}
                        </Button>
                        }
                    </div>
                </Card>
            </Col>
            <Col md={7} >
                <ListGroup>
                    <ListGroupItem className='listgroupitem-padding'>
                        <Card className='card-noborder'>
                            <Card.Body  className='listgroupcard-padding'>
                                <Card.Title>{texts.biop0}</Card.Title>
                                <Card.Text>
                                    {texts.biop1}<br/><br/>
                                    {texts.biop2}<br/><br/>
                                    {texts.biop3}<br/><br/>
                                    {texts.biop4}<br/><br/>
                                    {texts.biop5}<br/><br/>
                                </Card.Text>
                            </Card.Body>
                        </Card>
                    </ListGroupItem>
                    <ListGroupItem className='listgroupitem-padding'>
                        <Contacto/>
                    </ListGroupItem>
                </ListGroup>                
            </Col>
        </>
    )
}

export default Bio